    fn build(
        session_id: String,
        script_engine: std::sync::Arc<dyn sce_rust_runtime::IScriptEngine>,
    ) -> Self {
        Self {
            script_engine,
            pending_event_name: ::sce_rust_runtime::SceString::new(),
            pending_event_arrival_name: ::sce_rust_runtime::SceString::new(),
            pending_event_data: ::sce_rust_runtime::SceString::new(),
            pending_event_type: ::sce_rust_runtime::SceString::new(),
            pending_event_sendid: ::sce_rust_runtime::SceString::new(),
            pending_event_origin: None,
            pending_event_invokeid: ::sce_rust_runtime::SceString::new(),
            session_id: Some(session_id),
            script_engine_initialized: false,
            handed_values: sce_rust_runtime::helpers::invoke_processing::HandedValues::default(),
            basic_http_access_uri: String::new(),
            pending_invokes: Vec::new(),
            active_invokes: std::collections::HashMap::new(),
            child_by_param: None,
            pending_done_invoke_by_param: false,
            child_by_namelist: None,
            pending_done_invoke_by_namelist: false,
            child_late_bound: None,
            pending_done_invoke_late_bound: false,
            child_first_macrostep: None,
            pending_done_invoke_first_macrostep: false,
            invoke_starts_by_param: 0,
            invoke_starts_by_namelist: 0,
            invoke_starts_late_bound: 0,
            invoke_starts_first_macrostep: 0,
            parent_external_queue: None,
            invoke_id: String::new(),
            child_session_id: String::new(),
            parent_session_id: String::new(),
        }
    }

    /// Build the machine under a session id drawn from the operating system's
    /// randomness, a UUID version 4 (docs/adr/0045).
    ///
    /// Absent on a target with no source of randomness the runtime reads
    /// (`wasm32-unknown-unknown`): a host there gives the id, through
    /// [`new_with_session_id`](Self::new_with_session_id).
    #[cfg(not(any(target_os = "none", all(target_arch = "wasm32", target_os = "unknown"))))]
    pub fn new(script_engine: std::sync::Arc<dyn sce_rust_runtime::IScriptEngine>) -> Self {
        Self::build(
            ::sce_rust_runtime::helpers::session_id::drawn(),
            script_engine,
        )
    }

    /// Build the machine under the session id its host gives: the host's own
    /// name for the machine, say, or a fixed id a test holds a saved text to
    /// (docs/adr/0045, "Questions the owner answered" 2). `_sessionid` is bound
    /// here and kept until the session ends; a restore binds the saved id in
    /// its place, since the session carries on.
    ///
    /// With [`new_with_checked_session_id`](Self::new_with_checked_session_id),
    /// the way this machine is built on `wasm32-unknown-unknown`, which has no
    /// source of randomness the runtime reads.
    ///
    /// # Errors
    ///
    /// An id that is not an XML Nmtoken (the empty text, a space, a `#`) is
    /// refused with the reason, and no machine is built.
    pub fn new_with_session_id(
        session_id: &str,
        script_engine: std::sync::Arc<dyn sce_rust_runtime::IScriptEngine>,
    ) -> Result<Self, ::sce_rust_runtime::helpers::session_id::SessionIdRefusal> {
        Ok(Self::build(
            ::sce_rust_runtime::helpers::session_id::given(session_id)?,
            script_engine,
        ))
    }

    /// [`new_with_session_id`](Self::new_with_session_id) under an id already
    /// proven to be an XML Nmtoken (docs/adr/0073), so nothing is refused. With
    /// the id written as `sce_rust_runtime::session_id!("...")`, a bad one is a
    /// compile error and the program carries no run-time check of it.
    pub fn new_with_checked_session_id(
        session_id: ::sce_rust_runtime::helpers::session_id::SessionId,
        script_engine: std::sync::Arc<dyn sce_rust_runtime::IScriptEngine>,
    ) -> Self {
        Self::build(session_id.as_str().to_string(), script_engine)
    }

    /// The policy of a child its parent invokes, under the id the tree gives it,
    /// `<parent>.<invokeid>` (docs/adr/0045): formed by the parent from its own
    /// id and the invoke id, both held to the rule already, so it is not
    /// judged again.
    pub(crate) fn for_child(
        session_id: String,
        script_engine: std::sync::Arc<dyn sce_rust_runtime::IScriptEngine>,
    ) -> Self {
        Self::build(session_id, script_engine)
    }

    // docs/adr/0096: the script session this machine's executable content runs
    // in was established by its start (`do_initialize_data_model`), and a start
    // whose session could not be established was refused before anything
    // could reach here. Reaching here without one is a defect of the generated
    // code, not a condition of the run.
    fn assert_script_session(&self) {
        debug_assert!(
            self.script_engine_initialized,
            "the script session is established by the start, before any executable content runs"
        );
    }

